function BindLookup:Step(maxOperations, maxMilliseconds)
    if self.status ~= "planning" then return self.status end
    if Text(Call(GetBindLocation)) ~= self.name then
        self:Cancel()
        return self.status
    end
    local deadline = self.clock and (self.clock() + (maxMilliseconds or 1))
    for operation = 1, maxOperations or 32 do
        if operation > 1 and deadline and self.clock() >= deadline then break end
        local areaID, definition = next(self.bindings, self.cursor)
        self.cursor = areaID
        if not areaID then
            -- Missing area data gets another chance on the next world load.
            -- Keep the negative result for this session so each hearth variant
            -- does not restart the same scan.
            Adapter.bindLookup = { name = self.name, position = self.found or false }
            self.status = "ready"
            break
        end
        local areaName = Text(C_Map and Call(C_Map.GetAreaInfo, areaID))
        if areaName == self.name then
            local position = APR.NavigationData:NormalizeLocation(definition)
            if position then
                local found = self.found
                if found and (found.instanceID ~= position.instanceID
                    or (found.x - position.x)^2 + (found.y - position.y)^2 > 25) then
                    -- Identical inn names require an observed location when
                    -- their coordinates refer to different places.
                    Adapter.bindLookup = { name = self.name, position = false }
                    self.status = "ready"
                    break
                end
                self.found = position
            end
        end
    end
    return self.status
end--[[APR_DIAG]]; BindLookup.Step = APRTrace("APR-Core/features/navigation/NavigationAdapter.lua:76:BindLookup:Step#11", BindLookup.Step)--[[/APR_DIAG]]

