    local name = Text(Call(GetBindLocation))
    if not name then return nil end
    local observed = self:GetCharacterSettings().bindLocation
    if observed and observed.name == name then
        local position = self:SavedPosition(observed.location)
        if position then return position end
    end
    if not self.bindLookup or self.bindLookup.name ~= name then
