function Adapter:GetHousingData()
    if not C_Housing then return nil end
    local settings = self:GetCharacterSettings()
    local wanted = Text(Call(C_Housing.GetTrackedHouseGuid)) or settings.selectedHouseGUID
    local fallback
    for _, house in ipairs(self.houses) do
        if ValidHouse(house) then
            if house.houseGUID == wanted then return house end
            fallback = fallback or house
        end
    end
    if fallback then settings.selectedHouseGUID = fallback.houseGUID end
    return fallback
