function Adapter:GetHousingPosition()
    local house = self:GetHousingData()
    if not house then return nil end
    local mapID = Call(C_Housing.GetUIMapIDForNeighborhood, house.neighborhoodGUID)
    if not Number(mapID) then return nil end
    local current = Text(Call(C_Housing.GetCurrentNeighborhoodGUID))
    local settings = self:GetCharacterSettings()
    if current == house.neighborhoodGUID and C_HousingNeighborhood then
        local plots = Call(C_HousingNeighborhood.GetNeighborhoodMapData)
        for _, plot in ipairs(type(plots) == "table" and plots or {}) do
            if plot.plotID == house.plotID and plot.mapPosition then
                local x, y = plot.mapPosition.x, plot.mapPosition.y
                if Number(x) and Number(y) and x >= 0 and x <= 1 and y >= 0 and y <= 1 then
                    local position = { space = "map", uiMapID = mapID, x = x, y = y }
                    settings.housingPositions = settings.housingPositions or {}
                    settings.housingPositions[house.houseGUID] = position
                    return APR.NavigationData:NormalizeLocation(position)
                end
            end
        end
    end
    local saved = settings.housingPositions and settings.housingPositions[house.houseGUID]
    if saved and saved.uiMapID == mapID then return self:SavedPosition(saved) end
    return nil
end--[[APR_DIAG]]; Adapter.GetHousingPosition = APRTrace("APR-Core/features/navigation/NavigationAdapter.lua:171:Adapter:GetHousingPosition#17", Adapter.GetHousingPosition)--[[/APR_DIAG]]

