local function ReadActionUsability(kind, id, ignoreCooldown)
    if kind == "housing" then
        if not C_Housing or not Adapter:GetHousingData() then return false, "unknown" end
        if C_Housing.HasHousingExpansionAccess and Call(C_Housing.HasHousingExpansionAccess) ~= true then
            return false, "unavailable"
        end
        if C_Housing.IsHousingServiceEnabled and Call(C_Housing.IsHousingServiceEnabled) ~= true then
            return false, "unavailable"
        end
        local cooldown = Call(C_Housing.GetVisitCooldownInfo)
        if cooldown then
            if not Number(cooldown.startTime) or not Number(cooldown.duration) then return false, "restricted" end
            if cooldown.startTime + cooldown.duration > (GetTime and GetTime() or 0) then return false, "cooldown" end
        end
        if not Adapter:GetHousingPosition() then return false, "pending_data" end
        return true
    elseif kind == "housing_return" then
        local canReturn = Call(C_HousingNeighborhood and C_HousingNeighborhood.CanReturnAfterVisitingHouse)
        return canReturn == true, canReturn == nil and "pending_data" or nil
    end
    if not APR.GetRouteActionUsability then return false, "pending_data" end
    local usable, reason = Call(APR.GetRouteActionUsability, APR, kind, id, ignoreCooldown == true, true)
    if usable == nil then return false, "pending_data" end
    return usable == true, reason
end--[[APR_DIAG]]; ReadActionUsability = APRTrace("APR-Core/features/navigation/NavigationAdapter.lua:431:ReadActionUsability#48", ReadActionUsability)--[[/APR_DIAG]]

