local watchedActions = {}
function environment.getActionUsability(kind, id)
    local usable, reason = ReadActionUsability(kind, id)
    -- Only actions the catalogue actually checked can affect this character's
    -- journey. Unknown spells and missing items change through collection or
    -- inventory events, so ordinary cooldown events need not revisit them.
    local key = kind .. ":" .. tostring(id)
    if usable or reason == "cooldown" or reason == "restricted" or reason == "pending_data" or reason == "unusable" then
        local watched = watchedActions[key]
        if not watched then
            watched = { kind = kind, id = id }
            watchedActions[key] = watched
        end
        -- UI checks must not consume a transition before the cooldown job can
        -- notice it. Only that job advances an existing observation's value.
        if not watched.enabled then watched.usable, watched.reason = usable, reason end
        watched.enabled = true
    else
        -- Keep existing keys stable while a check is suspended between frames.
        local watched = watchedActions[key]
        if watched then watched.enabled = false end
    end
    return usable, reason
end--[[APR_DIAG]]; environment.getActionUsability = APRTrace("APR-Core/features/navigation/NavigationAdapter.lua:462:environment.getActionUsability#50", environment.getActionUsability)--[[/APR_DIAG]]

local CooldownCheck = {}
CooldownCheck.__index = CooldownCheck
function CooldownCheck:Step(maxOperations, maxMilliseconds)
    local deadline = self.clock and (self.clock() + (maxMilliseconds or 0.5))
    for operation = 1, maxOperations or 8 do
        if operation > 1 and deadline and self.clock() >= deadline then return "planning" end
        local key, watched = next(watchedActions, self.cursor)
        self.cursor = key
        if not key then return "ready", self.changed == true end
        if watched.enabled then
            local usable, reason = ReadActionUsability(watched.kind, watched.id)
            if usable ~= watched.usable or reason ~= watched.reason then
                watched.usable, watched.reason = usable, reason
                -- Shared cooldowns can change several actions at once. Finish
                -- the bounded scan so one transition requests only one replan.
                self.changed = true
            end
        end
    end
    return "planning"
end--[[APR_DIAG]]; CooldownCheck.Step = APRTrace("APR-Core/features/navigation/NavigationAdapter.lua:488:CooldownCheck:Step#51", CooldownCheck.Step)--[[/APR_DIAG]]

